// Descrizioni QR approvate dei gruppi completati.
(function () {
  window.QR_DESCR_I18N = window.QR_DESCR_I18N || {};

  Object.assign(window.QR_DESCR_I18N, {
    "Via Balbi su P.Principe": {
      it: "Via Balbi fu costruita tra il 1602 e il 1620, su iniziativa della nobile famiglia Balbi, ed è una famosa strada barocca del XVII secolo a Genova. Collega Piazza della Nunziata a Piazza Acquaverde, vicino alla stazione di Genova Principe, ed è celebre per i suoi magnifici palazzi nobiliari, molti dei quali fanno parte dei Palazzi dei Rolli.",
      en: "Via Balbi was built between 1602 and 1620 at the initiative of the noble Balbi family and is a famous seventeenth-century Baroque street in Genoa. It connects Piazza della Nunziata with Piazza Acquaverde, near Genova Principe railway station, and is renowned for its magnificent aristocratic palaces, many of which belong to the Rolli Palaces system.",
      es: "Via Balbi fue construida entre 1602 y 1620 por iniciativa de la noble familia Balbi y es una famosa calle barroca del siglo XVII de Génova. Une Piazza della Nunziata con Piazza Acquaverde, cerca de la estación de Genova Principe, y es célebre por sus magníficos palacios nobiliarios, muchos de los cuales forman parte de los Palacios de los Rolli.",
      fr: "La Via Balbi fut construite entre 1602 et 1620 à l’initiative de la noble famille Balbi. C’est une célèbre rue baroque du XVIIe siècle de Gênes. Elle relie la Piazza della Nunziata à la Piazza Acquaverde, près de la gare de Genova Principe, et doit sa renommée à ses magnifiques palais aristocratiques, dont beaucoup font partie des Palais des Rolli.",
      ar: "شُيّد شارع فيا بالبي بين عامي 1602 و1620 بمبادرة من عائلة بالبي النبيلة، وهو أحد أشهر شوارع جنوة الباروكية التي تعود إلى القرن السابع عشر. يربط بين ساحة ديلا نونتسياتا وساحة أكوافردي، بالقرب من محطة جنوة برينشيبي، ويشتهر بقصوره الأرستقراطية الرائعة، التي ينتمي كثير منها إلى منظومة قصور الرولي.",
      ru: "Улица Виа Бальби была построена между 1602 и 1620 годами по инициативе знатной семьи Бальби и является одной из знаменитых барочных улиц Генуи XVII века. Она соединяет площадь Пьяцца-делла-Нунциата с площадью Пьяцца-Аккуаверде, расположенной рядом с вокзалом Генуя Принчипе, и известна своими великолепными аристократическими дворцами, многие из которых входят в систему Дворцов Ролли.",
      zh: "巴尔比街建于1602年至1620年，由贵族巴尔比家族倡议修建，是热那亚著名的17世纪巴洛克风格街道。它连接农齐亚塔广场和阿夸韦尔德广场，靠近热那亚王子广场火车站，并以宏伟的贵族宫殿闻名，其中许多属于罗利宫殿体系。",
      lij: "Via Balbi a l’è stæta costruïa fra o 1602 e o 1620, pe iniçiativa da nòbile famiggia Balbi, e a l’è unn-a famosa stradda baròcca do XVII secolo a Zêna. A collega Piazza della Nunziata con Piazza Acquaverde, arente a-a staçion de Zêna Prinçipe, e a l’è famosa pe-i seu magnifici palaççi nobiliari, tanti di quæ fan parte di Palaççi di Rolli."
    },

    "Via Balbi da Piazza Durazzo": {
      it: "Piazza Durazzo è un piccolo e caratteristico spazio urbano del centro storico di Genova, situato nei pressi di via Balbi e del quartiere di Prè. Prende il nome dalla storica e influente famiglia Durazzo, che nel corso dei secoli possedette importanti palazzi e proprietà in quest’area della città.",
      en: "Piazza Durazzo is a small and distinctive urban space in Genoa’s historic centre, near Via Balbi and the Prè district. It is named after the historic and influential Durazzo family, which owned important palaces and properties in this part of the city over the centuries.",
      es: "Piazza Durazzo es un pequeño y característico espacio urbano del centro histórico de Génova, situado cerca de Via Balbi y del barrio de Prè. Debe su nombre a la histórica e influyente familia Durazzo, que a lo largo de los siglos poseyó importantes palacios y propiedades en esta zona de la ciudad.",
      fr: "La Piazza Durazzo est un petit espace urbain caractéristique du centre historique de Gênes, situé à proximité de la Via Balbi et du quartier de Prè. Elle doit son nom à l’ancienne et influente famille Durazzo, qui posséda au fil des siècles d’importants palais et propriétés dans cette partie de la ville.",
      ar: "ساحة دوراتسو مساحة حضرية صغيرة ومميزة في مركز جنوة التاريخي، تقع بالقرب من شارع فيا بالبي وحي بريه. تحمل الساحة اسم عائلة دوراتسو التاريخية والنافذة، التي امتلكت على مر القرون قصوراً وممتلكات مهمة في هذه المنطقة من المدينة.",
      ru: "Пьяцца Дуратцо — небольшое и характерное городское пространство в историческом центре Генуи, расположенное рядом с улицей Виа Бальби и кварталом Пре. Площадь названа в честь старинной и влиятельной семьи Дуратцо, которая на протяжении веков владела важными дворцами и другой недвижимостью в этой части города.",
      zh: "杜拉佐广场是热那亚历史中心一处小巧而富有特色的城市空间，靠近巴尔比街和普雷街区。广场得名于历史悠久且影响深远的杜拉佐家族；几个世纪以来，该家族在这一带拥有重要的宫殿和地产。",
      lij: "Piazza Durazzo a l’è un piccin e caratteristico spaçio urbano do çentro stöico de Zêna, arente a via Balbi e a-o quartier de Prè. A piggia o nomme da stöica e influente famiggia Durazzo, che inti secoli a l’à avuo importanti palaççi e propietæ inte sta parte da çitæ."
    },

    "Portici in piazza di Caricamento": {
      it: "I portici di Piazza Caricamento, noti come Sottoripa, sono i porticati pubblici più antichi d’Italia e risalgono al XII secolo: furono costruiti tra il 1125 e il 1133. Un tempo lambiti direttamente dal mare, proteggevano le botteghe e i magazzini delle merci sbarcate nel porto antico.",
      en: "The arcades of Piazza Caricamento, known as Sottoripa, are the oldest public arcades in Italy and date back to the twelfth century: they were built between 1125 and 1133. Once directly beside the sea, they sheltered the shops and warehouses used for goods unloaded in the old port.",
      es: "Los pórticos de Piazza Caricamento, conocidos como Sottoripa, son los pórticos públicos más antiguos de Italia y se remontan al siglo XII: fueron construidos entre 1125 y 1133. Antiguamente situados junto al mar, protegían las tiendas y los almacenes de las mercancías desembarcadas en el puerto antiguo.",
      fr: "Les arcades de la Piazza Caricamento, connues sous le nom de Sottoripa, sont les plus anciennes arcades publiques d’Italie et remontent au XIIe siècle : elles furent construites entre 1125 et 1133. Autrefois directement bordées par la mer, elles abritaient les boutiques et les entrepôts des marchandises débarquées dans le port ancien.",
      ar: "أروقة ساحة كاريكامينتو، المعروفة باسم سوتّوريبا، هي أقدم الأروقة العامة في إيطاليا وتعود إلى القرن الثاني عشر، إذ شُيّدت بين عامي 1125 و1133. كانت مياه البحر تصل إليها مباشرة، وكانت تحمي المتاجر والمخازن التي توضع فيها البضائع المفرّغة في الميناء القديم.",
      ru: "Аркады площади Пьяцца Карикаменто, известные как Сотторипа, считаются старейшими общественными аркадами Италии и относятся к XII веку: они были построены между 1125 и 1133 годами. Когда-то к ним непосредственно подступало море, а под сводами располагались лавки и склады для товаров, разгружавшихся в старом порту.",
      zh: "卡里卡门托广场的拱廊被称为索托里帕，是意大利现存最古老的公共拱廊，建于12世纪的1125年至1133年。过去海水曾直接抵达拱廊前方；这里为老港卸下的货物、店铺和仓库提供遮蔽。",
      lij: "I pòrteghi de Piazza Caricamento, conosciui comme Sottoripa, son i pòrteghi pubrichi ciù antighi d’Italia e risælan a-o XII secolo: son stæti costruïi fra o 1125 e o 1133. Un tempo o mâ o l’arrivava fin davanti a-i pòrteghi, che proteggeivan botteghe e magasæ di mercançie descaregæ into porto antigo."
    },

    "Piazza Raibetta": {
      it: "Piazza della Raibetta è una storica piazza del centro antico di Genova, situata nei pressi di Palazzo San Giorgio e di via San Lorenzo. Il suo nome deriva dall’arabo e ricorda l’antico mercato di legumi che vi si teneva nel Medioevo.",
      en: "Piazza della Raibetta is a historic square in Genoa’s old town, located near Palazzo San Giorgio and Via San Lorenzo. Its name is of Arabic origin and recalls the old market for pulses that was held here during the Middle Ages.",
      es: "Piazza della Raibetta es una plaza histórica del casco antiguo de Génova, situada cerca del Palazzo San Giorgio y de Via San Lorenzo. Su nombre es de origen árabe y recuerda el antiguo mercado de legumbres que se celebraba aquí durante la Edad Media.",
      fr: "La Piazza della Raibetta est une place historique de la vieille ville de Gênes, située près du Palazzo San Giorgio et de la Via San Lorenzo. Son nom est d’origine arabe et rappelle l’ancien marché de légumes secs qui s’y tenait au Moyen Âge.",
      ar: "ساحة ديلا رايبيتّا ساحة تاريخية في مدينة جنوة القديمة، تقع بالقرب من قصر سان جورجيو وشارع فيا سان لورينتسو. اسمها ذو أصل عربي ويذكّر بالسوق القديم للبقوليات الذي كان يُقام فيها خلال العصور الوسطى.",
      ru: "Пьяцца-делла-Райбетта — историческая площадь в старой части Генуи, расположенная недалеко от Палаццо Сан-Джорджо и улицы Виа Сан-Лоренцо. Её название имеет арабское происхождение и напоминает о средневековом рынке бобовых культур, который находился на этом месте.",
      zh: "拉伊贝塔广场是热那亚老城的一座历史广场，靠近圣乔治宫和圣洛伦佐街。它的名称源自阿拉伯语，使人想起中世纪时期曾在这里举行的豆类市场。",
      lij: "Piazza della Raibetta a l’è unn-a stöica ciassa do çentro antigo de Zêna, arente a Palazzo San Giorgio e a via San Lorenzo. O seu nomme o deriva da l’arabo e o ricòrda l’antigo mercato de legummi che se tegniva chi into Medioêvo."
    },

    "Piazza Caricamento su S.Giorgio": {
      it: "Piazza Caricamento è un nodo storico e urbano di Genova situato tra il Porto Antico e i celebri portici di Sottoripa. Realizzata nell’Ottocento su un’area precedentemente occupata dal mare, assunse il nome di Caricamento nel 1854, quando divenne il terminale ferroviario per il carico e lo scarico delle merci portuali. Sulla piazza si affaccia il monumentale Palazzo San Giorgio, storico edificio del XIII secolo.",
      en: "Piazza Caricamento is a historic urban landmark in Genoa, located between the Porto Antico and the famous Sottoripa arcades. Created in the nineteenth century on land previously occupied by the sea, it received the name Caricamento in 1854, when it became the railway terminal for loading and unloading port goods. The monumental thirteenth-century Palazzo San Giorgio overlooks the square.",
      es: "Piazza Caricamento es un importante núcleo histórico y urbano de Génova, situado entre el Porto Antico y los célebres pórticos de Sottoripa. Creada en el siglo XIX sobre un área anteriormente ocupada por el mar, recibió el nombre de Caricamento en 1854, cuando se convirtió en terminal ferroviaria para la carga y descarga de mercancías portuarias. A la plaza se asoma el monumental Palazzo San Giorgio, edificio histórico del siglo XIII.",
      fr: "La Piazza Caricamento est un important carrefour historique et urbain de Gênes, situé entre le Porto Antico et les célèbres arcades de Sottoripa. Aménagée au XIXe siècle sur un espace autrefois occupé par la mer, elle prit le nom de Caricamento en 1854, lorsqu’elle devint le terminus ferroviaire destiné au chargement et au déchargement des marchandises du port. Le monumental Palazzo San Giorgio, édifice historique du XIIIe siècle, donne sur la place.",
      ar: "تُعد ساحة كاريكامينتو معلماً تاريخياً وحضرياً مهماً في جنوة، وتقع بين الميناء القديم وأروقة سوتّوريبا الشهيرة. أُنشئت في القرن التاسع عشر فوق منطقة كانت تغمرها مياه البحر، وحملت اسم كاريكامينتو عام 1854 عندما أصبحت محطة نهائية للسكك الحديدية مخصّصة لتحميل بضائع الميناء وتفريغها. ويطل على الساحة قصر سان جورجيو الضخم، وهو مبنى تاريخي يعود إلى القرن الثالث عشر.",
      ru: "Пьяцца Карикаменто — важный исторический и городской узел Генуи, расположенный между Старым портом и знаменитыми аркадами Сотторипа. Площадь была создана в XIX веке на территории, прежде занятой морем, и получила название Карикаменто в 1854 году, когда стала железнодорожным терминалом для погрузки и разгрузки портовых товаров. На площадь выходит монументальный Палаццо Сан-Джорджо — историческое здание XIII века.",
      zh: "卡里卡门托广场是热那亚重要的历史和城市节点，位于老港与著名的索托里帕拱廊之间。广场于19世纪在原本被海水覆盖的区域建成，并于1854年因成为港口货物装卸铁路终点站而得名。宏伟的13世纪历史建筑圣乔治宫坐落在广场旁。",
      lij: "Piazza Caricamento a l’è un importante ponto stöico e urbano de Zêna, fra o Porto Antigo e i famoxi pòrteghi de Sottoripa. Realizzâ inte l’Ottocento in sce unn-a zöna primma occupâ da-o mâ, a l’à piggiou o nomme de Caricamento into 1854, quande a l’è deventâ o terminal ferroviario pe caregâ e descaregâ e mercançie do porto. In sciâ ciassa s’affaçça o monumentale Palazzo San Giorgio, stöico edifiçio do XIII secolo."
    },

    "Portici dal sottopassaggio": {
      it: "I portici di Piazza Caricamento, storicamente noti come Sottoripa, sono i portici pubblici più antichi d’Italia. Risalgono al XII secolo, nacquero a ridosso del mare e sono caratterizzati da basse volte medievali che ospitano botteghe storiche.",
      en: "The arcades of Piazza Caricamento, historically known as Sottoripa, are the oldest public arcades in Italy. Dating from the twelfth century, they were built beside the sea and are distinguished by low medieval vaults that still house historic shops.",
      es: "Los pórticos de Piazza Caricamento, conocidos históricamente como Sottoripa, son los pórticos públicos más antiguos de Italia. Se remontan al siglo XII, fueron construidos junto al mar y se caracterizan por sus bajas bóvedas medievales, que todavía albergan comercios históricos.",
      fr: "Les arcades de la Piazza Caricamento, historiquement connues sous le nom de Sottoripa, sont les plus anciennes arcades publiques d’Italie. Datant du XIIe siècle, elles furent construites au bord de la mer et se distinguent par leurs basses voûtes médiévales, qui abritent encore des boutiques historiques.",
      ar: "أروقة ساحة كاريكامينتو، المعروفة تاريخياً باسم سوتّوريبا، هي أقدم الأروقة العامة في إيطاليا. تعود إلى القرن الثاني عشر، وقد شُيّدت بمحاذاة البحر وتتميز بأقبية منخفضة من العصور الوسطى لا تزال تضم متاجر تاريخية.",
      ru: "Аркады площади Пьяцца Карикаменто, исторически известные как Сотторипа, являются старейшими общественными аркадами Италии. Они относятся к XII веку, были построены у самого моря и отличаются низкими средневековыми сводами, под которыми до сих пор работают исторические лавки.",
      zh: "卡里卡门托广场的拱廊历史上称为索托里帕，是意大利最古老的公共拱廊。它们建于12世纪，最初紧邻海岸，以低矮的中世纪拱顶为特色，如今拱廊下仍保留着历史悠久的店铺。",
      lij: "I pòrteghi de Piazza Caricamento, stöicamente conosciui comme Sottoripa, son i pòrteghi pubrichi ciù antighi d’Italia. Risælan a-o XII secolo, son nasciui arente a-o mâ e son caratterizzæ da basse vòtte medievali che ancon ancheu ospitan botteghe stöiche."
    },

    "Piazza Corvetto da Via XII ottobre": {
      it: "Piazza Corvetto fu realizzata nel 1877 nell’ambito delle trasformazioni ottocentesche del centro cittadino. Arrivando da via XII Ottobre, la piazza si apre attorno al monumento equestre a Vittorio Emanuele II, inaugurato nel 1886, con i giardini dell’Acquasola e Villetta Di Negro sui lati opposti.",
      en: "Piazza Corvetto was laid out in 1877 as part of the nineteenth-century transformation of Genoa’s city centre. Approaching from Via XII Ottobre, the square opens around the equestrian monument to Victor Emmanuel II, inaugurated in 1886, with the Acquasola gardens and Villetta Di Negro on opposite sides.",
      es: "Piazza Corvetto fue realizada en 1877 dentro de las transformaciones urbanas del centro de Génova durante el siglo XIX. Al llegar desde Via XII Ottobre, la plaza se abre alrededor del monumento ecuestre a Víctor Manuel II, inaugurado en 1886, con los jardines de Acquasola y Villetta Di Negro en lados opuestos.",
      fr: "La Piazza Corvetto fut aménagée en 1877 dans le cadre des transformations urbaines du centre de Gênes au XIXe siècle. En arrivant par la Via XII Ottobre, la place s’organise autour du monument équestre à Victor-Emmanuel II, inauguré en 1886, avec les jardins de l’Acquasola et la Villetta Di Negro de part et d’autre.",
      ar: "أُنشئت ساحة كورفيتو عام 1877 ضمن التحولات العمرانية التي شهدها وسط جنوة في القرن التاسع عشر. وعند الوصول من شارع فيا XII أوتّوبري، تنفتح الساحة حول النصب الفروسي لفيتوريو إيمانويل الثاني، الذي افتُتح عام 1886، فيما تقع حدائق أكواسولا وفيليتّا دي نيغرو على جانبين متقابلين.",
      ru: "Площадь Корветто была создана в 1877 году в ходе преобразований центра Генуи XIX века. При подходе со стороны Виа XII Оттобре площадь раскрывается вокруг конного памятника Виктору Эммануилу II, открытого в 1886 году; по противоположным сторонам находятся сады Аккуасола и Виллетта Ди Негро.",
      zh: "科尔韦托广场建于1877年，是19世纪热那亚市中心改造的一部分。从十二月十日街方向进入时，广场围绕1886年揭幕的维托里奥·埃马努埃莱二世骑马纪念碑展开，阿夸索拉花园与迪内格罗小公园分列两侧。",
      lij: "Piazza Corvetto a l’è stæta realizzâ into 1877, inte trasformazioni ottoçentesche do çentro da çitæ. Arrivando da Via XII Ottobre, a ciassa a s’arve intorno a-o monumento equestre a Vittorio Emanuele II, inaugurou into 1886, con i giardìn de l’Acquasola e Villetta Di Negro da-e due bande opposte."
    },

    "Piazza Corvetto da Via Piaggio": {
      it: "Da via Martin Piaggio, Piazza Corvetto appare dall’alto come uno snodo tra il centro ottocentesco e la circonvallazione a monte. La sistemazione della piazza, realizzata nel 1877, modificò profondamente quest’area, creando un raccordo monumentale tra nuove strade, edifici rappresentativi e spazi verdi storici.",
      en: "From Via Martin Piaggio, Piazza Corvetto appears from above as a junction between the nineteenth-century city centre and the upper ring road. The square’s layout, completed in 1877, profoundly transformed the area, creating a monumental connection between new streets, representative buildings and historic green spaces.",
      es: "Desde Via Martin Piaggio, Piazza Corvetto aparece desde lo alto como un enlace entre el centro decimonónico y la circunvalación de las colinas. La ordenación de la plaza, realizada en 1877, transformó profundamente la zona, creando una conexión monumental entre nuevas calles, edificios representativos y espacios verdes históricos.",
      fr: "Depuis la Via Martin Piaggio, la Piazza Corvetto apparaît en hauteur comme un carrefour entre le centre du XIXe siècle et la circonvallation des collines. Son aménagement, réalisé en 1877, transforma profondément le secteur en créant une liaison monumentale entre nouvelles rues, édifices représentatifs et espaces verts historiques.",
      ar: "من شارع فيا مارتن بياجّو تبدو ساحة كورفيتو من الأعلى كعقدة تربط وسط المدينة الذي تطور في القرن التاسع عشر بالطريق الدائري المرتفع. وقد غيّر تنظيم الساحة، المنجز عام 1877، المنطقة بعمق، فأنشأ رابطاً معمارياً بارزاً بين شوارع جديدة ومبانٍ تمثيلية ومساحات خضراء تاريخية.",
      ru: "С улицы Виа Мартин Пьяджо площадь Корветто видна сверху как узел между центром XIX века и верхней кольцевой дорогой. Планировка площади, завершённая в 1877 году, глубоко изменила этот район, создав монументальную связь между новыми улицами, представительными зданиями и историческими зелёными зонами.",
      zh: "从马丁·皮亚乔街俯瞰，科尔韦托广场像是19世纪城市中心与山上环城道路之间的交通节点。1877年完成的广场改造深刻改变了这一地区，以纪念性布局连接起新道路、代表性建筑和历史绿地。",
      lij: "Da Via Martin Piaggio, Piazza Corvetto a se vedde da l’erto comme un nodo fra o çentro ottoçentesco e a çirconvallaçion a monte. A sistemmaçion da ciassa, realizzâ into 1877, a l’à cambiou profondamente sta zöna, creando un raccordo monumentale fra stradde neuve, edifici rappresentativi e spaçi verdi stöichi."
    },

        "San Marco al Molo": {
      it: "La chiesa di San Marco al Molo fu fondata nel 1173 e costruita sui primi ampliamenti artificiali del molo. In origine si affacciava direttamente sulla banchina del porto; l’espansione delle aree portuali e urbane l’ha progressivamente inglobata nel fitto tessuto edilizio circostante.",
      en: "The church of San Marco al Molo was founded in 1173 and built on the first artificial extensions of the pier. Originally it faced directly onto the harbour quay; the expansion of the port and urban areas gradually incorporated it into the dense surrounding fabric of buildings.",
      es: "La iglesia de San Marco al Molo fue fundada en 1173 y construida sobre las primeras ampliaciones artificiales del muelle. Originalmente daba directamente al embarcadero del puerto; la expansión de las áreas portuarias y urbanas la fue integrando progresivamente en el denso tejido de edificios que la rodea.",
      fr: "L’église San Marco al Molo fut fondée en 1173 et construite sur les premiers agrandissements artificiels du môle. À l’origine, elle donnait directement sur le quai du port ; l’expansion des zones portuaires et urbaines l’a progressivement intégrée au dense tissu bâti environnant.",
      ar: "تأسست كنيسة سان ماركو أل مولو عام 1173 وبُنيت فوق أولى التوسعات الاصطناعية للرصيف البحري. وكانت في الأصل تطل مباشرة على رصيف الميناء؛ ثم أدّى توسع المناطق المينائية والعمرانية إلى اندماجها تدريجيًا داخل النسيج العمراني الكثيف المحيط بها.",
      ru: "Церковь Сан-Марко-аль-Моло была основана в 1173 году и построена на первых искусственных расширениях мола. Первоначально она выходила прямо к портовой набережной; расширение портовых и городских территорий постепенно включило её в плотную окружающую застройку.",
      zh: "圣马可阿尔莫洛教堂始建于1173年，建在码头最早的人工扩建区域上。最初教堂直接面向港口码头；随着港区和城市空间不断扩展，它逐渐被周围密集的建筑群包围并融入其中。",
      lij: "A gexa de San Marco al Molo a fu fondâ into 1173 e costruïa in sci primi ampliamenti artifiçiæ do molo. In origine a dava direttamente in sciâ banchinn-a do porto; l’espanscion de aree portuali e urban-e a l’ha poi incorporâ poco a poco into fitto tessuo de case intorno."
    },

        "Porta Siberia": {
      it: "La Porta del Molo, conosciuta come Porta Siberia, fu progettata da Galeazzo Alessi nel Cinquecento e completata nel 1553. Inserita nelle mura portuali, univa funzioni difensive e di accesso alla città, controllando uno dei principali passaggi tra il porto e lo storico quartiere del Molo.",
      en: "The Porta del Molo, known as Porta Siberia, was designed by Galeazzo Alessi in the sixteenth century and completed in 1553. Set into the harbour walls, it combined defensive and city-access functions, controlling one of the main passages between the port and the historic Molo district.",
      es: "La Porta del Molo, conocida como Porta Siberia, fue proyectada por Galeazzo Alessi en el siglo XVI y terminada en 1553. Integrada en las murallas portuarias, combinaba funciones defensivas y de acceso a la ciudad, controlando uno de los principales pasos entre el puerto y el histórico barrio del Molo.",
      fr: "La Porta del Molo, connue sous le nom de Porta Siberia, fut conçue par Galeazzo Alessi au XVIe siècle et achevée en 1553. Intégrée aux murailles du port, elle associait fonctions défensives et accès à la ville, contrôlant l’un des principaux passages entre le port et le quartier historique du Molo.",
      ar: "صمّم غالياتسو أليسي «بوابة المولو»، المعروفة باسم «بورتا سيبيريا»، في القرن السادس عشر، واكتمل بناؤها عام 1553. وكانت جزءًا من أسوار الميناء، تجمع بين الوظيفة الدفاعية وتأمين الدخول إلى المدينة، وتراقب أحد أهم الممرات بين الميناء وحي مولو التاريخي.",
      ru: "Ворота Порта-дель-Моло, известные как Порта-Сиберия, были спроектированы Галеаццо Алесси в XVI веке и завершены в 1553 году. Встроенные в портовые стены, они сочетали оборонительную функцию с городским входом и контролировали один из главных проходов между портом и историческим кварталом Моло.",
      zh: "莫洛门（Porta del Molo），通常称为西伯利亚门，由加莱亚佐·阿莱西于16世纪设计，并于1553年建成。它嵌入港口城墙之中，兼具防御和城市入口功能，控制着港口与历史悠久的莫洛街区之间的重要通道之一。",
      lij: "A Porta del Molo, conosciua comme Porta Siberia, a fu progettâ da Galeazzo Alessi into Cinqueçento e completâ into 1553. Inseria inte miage do porto, a metteiva insieme fonçioin defensive e d’accesso a-a çittæ, controlando un di principali passaggi tra o porto e o stöico quartier do Môlo."
    },

    "Via Roma": {
      it: "Via Roma è una delle strade più eleganti e monumentali di Genova, realizzata negli anni Settanta dell’Ottocento per collegare Piazza Corvetto a Piazza De Ferrari. Caratterizzata da sontuosi palazzi ottocenteschi in stile eclettico, ospita boutique di alta moda e botteghe storiche ed è affiancata dalla suggestiva Galleria Mazzini.",
      en: "Via Roma is one of Genoa’s most elegant and monumental streets. It was built in the 1870s to connect Piazza Corvetto with Piazza De Ferrari. Lined with sumptuous nineteenth-century buildings in an eclectic style, it is home to luxury fashion boutiques and historic shops and runs alongside the striking Galleria Mazzini.",
      es: "Via Roma es una de las calles más elegantes y monumentales de Génova. Fue construida en la década de 1870 para unir Piazza Corvetto con Piazza De Ferrari. Flanqueada por suntuosos edificios decimonónicos de estilo ecléctico, alberga boutiques de alta moda y comercios históricos y discurre junto a la sugestiva Galleria Mazzini.",
      fr: "La Via Roma est l’une des rues les plus élégantes et monumentales de Gênes. Elle fut aménagée dans les années 1870 pour relier la Piazza Corvetto à la Piazza De Ferrari. Bordée de somptueux palais du XIXe siècle de style éclectique, elle accueille des boutiques de haute couture et des commerces historiques et longe l’élégante Galleria Mazzini.",
      ar: "يُعد شارع فيا روما واحداً من أكثر شوارع جنوة أناقة وضخامة. أُنشئ في سبعينيات القرن التاسع عشر ليربط بين ساحة كورفيتّو وساحة دي فيرّاري. تصطف على جانبيه مبانٍ فخمة من القرن التاسع عشر مبنية بأسلوب انتقائي، ويضم متاجر للأزياء الراقية ومحال تاريخية، كما يمتد بمحاذاة غاليريا ماتسيني الجميلة.",
      ru: "Виа Рома — одна из самых элегантных и монументальных улиц Генуи. Она была проложена в 1870-х годах, чтобы соединить площадь Корветто с площадью Де Феррари. Вдоль неё расположены роскошные здания XIX века в эклектичном стиле, бутики высокой моды и исторические магазины, а рядом проходит живописная Галерея Мадзини.",
      zh: "罗马街是热那亚最优雅、最具纪念性的大街之一，修建于19世纪70年代，用于连接科尔韦托广场和德·费拉里广场。街道两旁排列着采用折衷主义风格建造的华丽19世纪建筑，汇集了高级时装店和历史老店，旁边则是迷人的马志尼拱廊。",
      lij: "Via Roma a l’è unn-a de stradde ciù eleganti e monumentali de Zêna, realizzâ inti anni Settanta de l’Ottocento pe collegâ Piazza Corvetto con Piazza De Ferrari. Caratterizzâ da sontuoxi palaççi ottoçenteschi in stile eclettico, a l’ospita boutique d’erta mòdda e botteghe stöiche ed a l’è affiancâ da-a suggestiva Galleria Mazzini."
    },

    "Pozzo": {
      it: "Costruito nel XVII secolo, il pozzo pubblico è un elegante chiosco a pianta ottagonale, sorretto da colonnine in marmo e coperto da una cupoletta sormontata dalla scultura di Giano Bifronte, il leggendario fondatore di Genova.",
      en: "Built in the 17th century, the public well is an elegant octagonal pavilion supported by small marble columns and covered by a dome topped with a sculpture of two-faced Janus, the legendary founder of Genoa.",
      es: "Construido en el siglo XVII, el pozo público es un elegante templete de planta octogonal, sostenido por pequeñas columnas de mármol y cubierto por una cúpula coronada por la escultura de Jano bifronte, el legendario fundador de Génova.",
      fr: "Construit au XVIIe siècle, le puits public est un élégant kiosque de plan octogonal, soutenu par de petites colonnes en marbre et couvert d’une coupole surmontée d’une sculpture de Janus aux deux visages, fondateur légendaire de Gênes.",
      ar: "شُيّد البئر العام في القرن السابع عشر، وهو عبارة عن جناح أنيق ثماني الأضلاع، تدعمه أعمدة رخامية صغيرة وتغطيه قبة تعلوها منحوتة للإله يانوس ذي الوجهين، المؤسس الأسطوري لمدينة جنوة.",
      ru: "Построенный в XVII веке общественный колодец представляет собой изящный восьмиугольный павильон, поддерживаемый небольшими мраморными колоннами. Его купол венчает скульптура двуликого Януса, легендарного основателя Генуи.",
      zh: "这座公共水井建于17世纪，是一座优雅的八角形亭阁，由小型大理石柱支撑，顶部覆盖小圆顶，圆顶上方矗立着双面雅努斯的雕像。传说中，雅努斯是热那亚的创建者。",
      lij: "Costruïo into XVII secolo, o posso pubblico o l’é un elegante chiosco a pianta otagonâ, sostegnûo da colonnette de marmo e coverto da ’na cupoletta con in çimma a scultura de Giano Bifronte, o fondatô leggendäio de Zena."
    },

    "Via Fieschi": {
      it: "Via Fieschi fu aperta tra il 1865 e il 1870 su un progetto ideato da Carlo Barabino decenni prima. Collegava Carignano a piazza Ponticello; negli anni Trenta del Novecento fu prolungata verso via XX Settembre, mentre le trasformazioni successive modificarono profondamente il quartiere circostante.",
      en: "Via Fieschi was opened between 1865 and 1870, following a plan devised decades earlier by Carlo Barabino. It linked Carignano with Piazza Ponticello; in the 1930s it was extended towards Via XX Settembre, while later redevelopment profoundly transformed the surrounding district.",
      es: "Via Fieschi fue abierta entre 1865 y 1870 a partir de un proyecto concebido décadas antes por Carlo Barabino. Unía Carignano con Piazza Ponticello; en la década de 1930 se prolongó hacia Via XX Settembre, mientras que las transformaciones posteriores modificaron profundamente el barrio circundante.",
      fr: "La Via Fieschi fut ouverte entre 1865 et 1870 d’après un projet conçu plusieurs décennies auparavant par Carlo Barabino. Elle reliait Carignano à la Piazza Ponticello ; dans les années 1930, elle fut prolongée vers la Via XX Settembre, tandis que les transformations ultérieures modifièrent profondément le quartier environnant.",
      ar: "افتُتح شارع فيا فييسكي بين عامي 1865 و1870 وفق مشروع وضعه كارلو بارابينو قبل ذلك بعقود. كان يربط كارينيانو بساحة بونتيتشيلّو؛ وفي ثلاثينيات القرن العشرين مُدّد باتجاه فيا XX سيتّيمبري، ثم غيّرت التحولات العمرانية اللاحقة المنطقة المحيطة بصورة عميقة.",
      ru: "Виа Фиески была проложена между 1865 и 1870 годами по проекту, задуманному Карло Барабино несколькими десятилетиями ранее. Она соединяла Кариньяно с Пьяцца Понтичелло; в 1930-е годы улицу продлили к Виа XX Сеттембре, а последующие перестройки существенно изменили окружающий район.",
      zh: "菲耶斯基街于1865年至1870年间开辟，依据的是卡洛·巴拉比诺数十年前提出的规划。它曾连接卡里尼亚诺与蓬蒂切洛广场；20世纪30年代又向九月二十日街方向延伸，之后的城市改造进一步深刻改变了周边街区。",
      lij: "Via Fieschi a l’è stæta averta fra o 1865 e o 1870, seguendo un progetto pensou da Carlo Barabino tanti anni primma. A collegava Carignano con Ciassa Ponticello; inti anni Trenta do Neuveçento a l’è stæta allongâ verso Via XX Settembre, e e trasformazioni vegnue dòppo an cambiou profondamente o quartê d’intorno."
    },

    "Seno di Giano": {
      it: "Fino alla fine dell’Ottocento, in questa zona le Mura delle Grazie segnavano il limite della città verso il mare, che arrivava direttamente ai loro piedi. La costruzione della Circonvallazione a mare allontanò la linea di costa, trasformando radicalmente il rapporto tra le mura, il porto e il litorale.",
      en: "Until the late nineteenth century, the Mura delle Grazie marked the city’s boundary towards the sea here, with the water reaching directly to their base. The construction of the Circonvallazione a mare moved the shoreline farther away, radically changing the relationship between the walls, the port and the coast.",
      es: "Hasta finales del siglo XIX, en esta zona las Mura delle Grazie marcaban el límite de la ciudad hacia el mar, cuyas aguas llegaban directamente a sus pies. La construcción de la Circonvallazione a mare alejó la línea de costa y transformó radicalmente la relación entre las murallas, el puerto y el litoral.",
      fr: "Jusqu’à la fin du XIXe siècle, les Mura delle Grazie marquaient ici la limite de la ville vers la mer, dont les eaux arrivaient directement à leur pied. La construction de la Circonvallazione a mare éloigna le rivage et transforma profondément le rapport entre les murailles, le port et le littoral.",
      ar: "حتى أواخر القرن التاسع عشر كانت أسوار Mura delle Grazie تمثّل هنا حدّ المدينة من جهة البحر، وكانت المياه تصل مباشرة إلى أسفلها. وأدّى إنشاء طريق Circonvallazione a mare إلى إبعاد خط الساحل، فغيّر جذرياً العلاقة بين الأسوار والميناء والواجهة البحرية.",
      ru: "До конца XIX века стены Мура-делле-Грацие здесь обозначали границу города со стороны моря, вода подходила прямо к их основанию. Строительство набережной Circonvallazione a mare отодвинуло береговую линию и радикально изменило соотношение между стенами, портом и побережьем.",
      zh: "直到19世纪末，格拉齐耶城墙在这一带仍标志着城市面向大海的边界，海水直接抵达城墙脚下。滨海环路 Circonvallazione a mare 的修建使海岸线向外推移，彻底改变了城墙、港口与海岸之间的关系。",
      lij: "Fin a-a fin de l’Ottocento, inte sta zöna e Mûage de Graçie segnâvan o confìn da çitæ verso o mâ, che o l’arrivava finn-a-i seu pé. A costruçion da Circonvallaçion a mâ a l’à allontanou a linia da costa, cambiando profondamente o rapporto fra e mûage, o porto e o litorâ."
    },

    "Via V maggio dal ponte": {
      it: "Via V Maggio è una celebre strada costiera di Genova situata nel quartiere di Quarto dei Mille. Nota per la spettacolare vista sul mare e per le spiagge e i locali che la costeggiano, ospita il monumento ai Mille, eretto poco lontano dallo scoglio dal quale Giuseppe Garibaldi e i Mille salparono nel 1860.",
      en: "Via V Maggio is a famous coastal road in Genoa’s Quarto dei Mille district. Known for its spectacular sea views and for the beaches and venues along its route, it is home to the Monument to the Thousand, erected near the rock from which Giuseppe Garibaldi and his Thousand set sail in 1860.",
      es: "Via V Maggio es una célebre calle costera de Génova situada en el barrio de Quarto dei Mille. Conocida por sus espectaculares vistas al mar y por las playas y locales que la bordean, alberga el Monumento a los Mil, erigido cerca del escollo desde el que Giuseppe Garibaldi y sus Mil zarparon en 1860.",
      fr: "La Via V Maggio est une célèbre route côtière de Gênes située dans le quartier de Quarto dei Mille. Connue pour sa vue spectaculaire sur la mer ainsi que pour les plages et les établissements qui la bordent, elle accueille le monument des Mille, érigé près du rocher d’où Giuseppe Garibaldi et ses Mille partirent en 1860.",
      ar: "يُعد شارع «فيا في ماجّو» من أشهر الطرق الساحلية في جنوة، ويقع في حي كوارتو دي ميلّه. يشتهر بإطلالته الرائعة على البحر وبالشواطئ والمرافق الممتدة على جانبيه، كما يضم نصب الألف، المقام بالقرب من الصخرة التي أبحر منها جوزيبي غاريبالدي ورجاله الألف عام 1860.",
      ru: "Виа V Маджо — известная прибрежная улица Генуи, расположенная в районе Кварто-деи-Милле. Она славится великолепным видом на море, пляжами и заведениями вдоль побережья. Здесь находится памятник Тысяче, установленный неподалёку от скалы, откуда Джузеппе Гарибальди и его Тысяча отплыли в 1860 году.",
      zh: "五月五日街是热那亚著名的滨海道路，位于千人远征纪念区。这里以壮丽的海景以及沿途的海滩和休闲场所闻名。街道附近矗立着“千人纪念碑”，离1860年朱塞佩·加里波第率领千人远征军启航的礁石不远。",
      lij: "Via V Mazzo a l’é ’na famosa stradda da costa de Zena, into quartê de Quarto dei Mille. Conosciûa pe-a seu spettacolosa vista in sce-o mâ e pe-e spiagge e i locali che ghe son longo, a l’ospita o monumento ai Mille, tiô sciù apreuvo a-o scheuggio donde Giuseppe Garibaldi e i Mille son partii into 1860."
    },

    "Villa De Ferrari": {
      it: "Villa De Ferrari includeva una storica dimora e un monastero delle Benedettine. L’intero complesso, situato dove oggi sorge l’edificio delle Poste, fu gradualmente demolito e spianato nei primi anni del Novecento per fare spazio allo sviluppo urbanistico e viario del quartiere.",
      en: "Villa De Ferrari comprised a historic residence and a Benedictine convent. The entire complex, located where the Post Office building now stands, was gradually demolished and the site levelled in the early 20th century to make way for the district’s urban and road development.",
      es: "Villa De Ferrari comprendía una residencia histórica y un monasterio benedictino. Todo el complejo, situado donde hoy se levanta el edificio de Correos, fue demolido y nivelado gradualmente a principios del siglo XX para dar paso al desarrollo urbano y viario del barrio.",
      fr: "La Villa De Ferrari comprenait une demeure historique et un monastère bénédictin. L’ensemble, situé à l’emplacement actuel du bâtiment de la Poste, fut progressivement démoli et le terrain nivelé au début du XXe siècle pour permettre le développement urbain et routier du quartier.",
      ar: "كان مجمّع فيلا دي فيرّاري يضم مسكناً تاريخياً وديراً للراهبات البندكتيات. وقد هُدم المجمع بأكمله تدريجياً وسُوّيت أرضه في أوائل القرن العشرين لإفساح المجال أمام التطور العمراني وشبكة الطرق في الحي، وذلك في الموقع الذي يشغله اليوم مبنى البريد.",
      ru: "Комплекс виллы Де Феррари включал историческую резиденцию и бенедиктинский монастырь. В начале XX века весь комплекс, находившийся на месте современного здания почты, постепенно снесли, а участок выровняли, чтобы освободить пространство для городской застройки и развития дорожной сети района.",
      zh: "德·费拉里别墅建筑群曾包括一座历史宅邸和一所本笃会修女院。整个建筑群位于如今邮局大楼所在的位置，并于20世纪初逐渐被拆除和平整，以便推进该街区的城市建设和道路发展。",
      lij: "Villa De Ferrari a comprendeiva ’na dimöa stöica e un monastê de Benedettinn-e. Tutto o complesso, ch’o l’êa dove ancheu gh’é o palaçio de Poste, o l’é stæto demolîo pöco pe votta e o terreno o l’é stæto spianou a-o prinçipio do Neuveçento, pe fâ spaçio a-o sviluppo urbanistico e da viabilitæ do quartê."
    },

    "Via Gianelli": {
      it: "Via Gianelli è il suggestivo e frequentato lungomare del quartiere di Quinto al Mare ed è la prosecuzione naturale di Via V Maggio. La strada offre una passeggiata pedonale con vista sul mare e sugli stabilimenti balneari.",
      en: "Via Gianelli is the picturesque and popular seafront promenade of the Quinto al Mare district and the natural continuation of Via V Maggio. The road offers a pedestrian walk overlooking the sea and the bathing establishments.",
      es: "Via Gianelli es el pintoresco y concurrido paseo marítimo del barrio de Quinto al Mare y constituye la prolongación natural de Via V Maggio. La calle ofrece un recorrido peatonal con vistas al mar y a los establecimientos de playa.",
      fr: "La Via Gianelli est la promenade maritime pittoresque et très fréquentée du quartier de Quinto al Mare, ainsi que le prolongement naturel de la Via V Maggio. Elle offre un parcours piéton avec vue sur la mer et les établissements balnéaires.",
      ar: "يُعد شارع جيانيلّي الواجهة البحرية الجميلة والشعبية في حي كوينتو آل ماري، وهو الامتداد الطبيعي لشارع فيا في ماجّو. ويوفر ممشى للمشاة يطل على البحر والمنشآت الشاطئية.",
      ru: "Виа Джанелли — живописная и популярная набережная района Квинто-аль-Маре и естественное продолжение Виа V Маджо. Вдоль улицы проходит пешеходный маршрут с видом на море и пляжные комплексы.",
      zh: "贾内利街是昆托滨海区风景优美且广受欢迎的海滨大道，也是五月五日街的自然延伸。这里设有步行路线，可以眺望大海和沿岸的海滨浴场。",
      lij: "Via Gianelli a l’é o suggestivo e frequentou lungomâ do quartê de Quinto a-o Mâ e a l’é a continuaçion naturale de Via V Mazzo. A stradda a l’offre ’na passegiâ pe-i pedoin co-a vista in sce-o mâ e in sci stabilimenti balneari."
    },

    "Via Quinto verso levante": {
      it: "Via Quinto è la storica arteria viaria che attraversa il cuore dell’omonimo quartiere del levante genovese, correndo parallela al lungomare di Via Gianelli. Corrispondente all’antico tracciato della Via Aurelia, mantiene un’atmosfera tipicamente ligure, alternando palazzine storiche e tradizionali attività commerciali ed essendo affiancata dalle caratteristiche crêuze che scendono verso il mare.",
      en: "Via Quinto is the historic road running through the heart of the district of the same name in eastern Genoa, parallel to the Via Gianelli seafront. Following the ancient route of the Via Aurelia, it retains a typically Ligurian atmosphere, with historic buildings, traditional shops and characteristic crêuze descending towards the sea.",
      es: "Via Quinto es la histórica arteria que atraviesa el corazón del barrio homónimo, en el este de Génova, paralela al paseo marítimo de Via Gianelli. Correspondiente al antiguo trazado de la Vía Aurelia, conserva una atmósfera típicamente ligur, alternando edificios históricos, comercios tradicionales y las características crêuze que descienden hacia el mar.",
      fr: "La Via Quinto est l’axe historique qui traverse le cœur du quartier du même nom, dans l’est de Gênes, parallèlement au front de mer de la Via Gianelli. Suivant l’ancien tracé de la Via Aurelia, elle conserve une atmosphère typiquement ligure, avec des immeubles anciens, des commerces traditionnels et les crêuze caractéristiques qui descendent vers la mer.",
      ar: "يُعد شارع كوينتو الطريق التاريخي الذي يعبر قلب الحي الذي يحمل الاسم نفسه في شرق جنوة، ويمتد موازياً لواجهة شارع جيانيلّي البحرية. وهو يتبع المسار القديم لطريق أوريليا، ويحافظ على أجواء ليغورية أصيلة تجمع بين المباني التاريخية والمتاجر التقليدية وممرات «كروزه» المميزة المنحدرة نحو البحر.",
      ru: "Виа Квинто — историческая дорога, проходящая через центр одноимённого района на востоке Генуи параллельно набережной Виа Джанелли. Она следует древнему маршруту Виа Аурелия и сохраняет типично лигурийскую атмосферу благодаря старинным домам, традиционным магазинам и характерным дорожкам-крёзе, спускающимся к морю.",
      zh: "昆托街是一条历史悠久的道路，穿过热那亚东部同名街区的中心，与贾内利海滨大道平行。它沿袭了古代奥雷利亚大道的路线，历史建筑、传统商铺和通向大海的特色“克勒兹”小径共同保留了典型的利古里亚氛围。",
      lij: "Via Quinto a l’é a stöica arteria ch’a passa into cheu do quartê do levante zeneize co-o mæximo nomme, parallela a-o lungomâ de Via Gianelli. A segue l’antigo tracciou da Via Aurelia e a conserva ’na atmosfera tipicamente ligure, fra palazzinn-e stöiche, botteghe tradiçionali e e caratteristiche crêu­ze che van zu verso o mâ."
    },

    "Caserma di San Benigno": {
      it: "Le Caserme di San Benigno erano un imponente complesso militare ottocentesco situato sul colle omonimo, il promontorio roccioso che storicamente separava il centro di Genova da Sampierdarena, nei pressi della Lanterna.",
      en: "The San Benigno Barracks were an imposing 19th-century military complex situated on the hill of the same name, the rocky promontory that historically separated central Genoa from Sampierdarena, near the Lanterna lighthouse.",
      es: "Los Cuarteles de San Benigno eran un imponente complejo militar del siglo XIX situado en la colina del mismo nombre, el promontorio rocoso que históricamente separaba el centro de Génova de Sampierdarena, cerca de la Linterna.",
      fr: "Les casernes de San Benigno formaient un imposant complexe militaire du XIXe siècle situé sur la colline du même nom, le promontoire rocheux qui séparait historiquement le centre de Gênes de Sampierdarena, près de la Lanterna.",
      ar: "كانت ثكنات سان بينينيو مجمّعاً عسكرياً ضخماً يعود إلى القرن التاسع عشر، وأقيمت على التل الذي يحمل الاسم نفسه، وهو الرأس الصخري الذي كان يفصل تاريخياً وسط جنوة عن سامبييردارينا بالقرب من منارة لانترنا.",
      ru: "Казармы Сан-Бениньо представляли собой внушительный военный комплекс XIX века, располагавшийся на одноимённом холме — скалистом мысе, который исторически отделял центр Генуи от Сампьердарены неподалёку от маяка Лантерна.",
      zh: "圣贝尼尼奥军营曾是一座宏伟的19世纪军事建筑群，坐落在同名山丘上。这处岩石岬角靠近热那亚灯塔，历史上曾将热那亚市中心与桑皮耶达雷纳分隔开来。",
      lij: "E Caserme de San Benigno ëan un imponente complesso militare de l’Ottoçento, sciâ colinn-a co-o mæximo nomme: o promontöio de rocca che stöicamente o separava o çentro de Zena da Sampêdænn-a, apreuvo a-a Lanterna."
    },

    "Via Caprera": {
      it: "Via Caprera si sviluppa sul viadotto che supera la valletta del torrente Vernazza e collega piazza Sturla con il quartiere verso ponente. La sua realizzazione, nel corso delle trasformazioni viarie del Novecento, modificò un’area precedentemente segnata da corsi d’acqua, creuze e piccoli nuclei abitati.",
      en: "Via Caprera runs across the viaduct spanning the small valley of the Vernazza stream and links Piazza Sturla with the neighbourhood to the west. Its construction, during twentieth-century road improvements, transformed an area previously shaped by watercourses, traditional creuze paths and small clusters of houses.",
      es: "Via Caprera discurre sobre el viaducto que salva el pequeño valle del torrente Vernazza y conecta Piazza Sturla con el barrio hacia poniente. Su construcción, dentro de las transformaciones viarias del siglo XX, modificó una zona antes marcada por cursos de agua, antiguas creuze y pequeños núcleos de viviendas.",
      fr: "La Via Caprera emprunte le viaduc qui franchit la petite vallée du torrent Vernazza et relie Piazza Sturla au quartier situé vers l’ouest. Sa réalisation, dans le cadre des transformations routières du XXe siècle, modifia un secteur auparavant marqué par les cours d’eau, les anciennes creuze et de petits noyaux d’habitat.",
      ar: "يمتد شارع كابريرا فوق الجسر الذي يعبر الوادي الصغير لنهر فيرنازا، ويربط ساحة ستورلا بالحي الواقع إلى الغرب. وقد أدى إنشاؤه، ضمن تحولات شبكة الطرق في القرن العشرين، إلى تغيير منطقة كانت من قبل تتسم بالمجاري المائية ومسارات «الكرويزه» التقليدية وتجمعات سكنية صغيرة.",
      ru: "Виа Капрера проходит по виадуку над небольшой долиной ручья Вернацца и связывает Пьяцца Стурла с районом к западу. Ее строительство в ходе дорожных преобразований XX века изменило территорию, прежде сформированную водотоками, традиционными генуэзскими дорожками-креузами и небольшими группами домов.",
      zh: "卡普雷拉街沿跨越韦尔纳扎溪小谷地的高架桥延伸，将斯图尔拉广场与西侧街区连接起来。它在20世纪道路改造过程中建成，改变了这一原本由溪流、热那亚传统坡道“creuze”和小型居民聚落构成的区域。",
      lij: "Via Caprera a passa in sce-o viadotto che o supera a valetta do rio Vernazza e a collega piazza Sturla co-o quartê verso ponente. A seu realizaçion, durante e trasformaçioin viâie do Novecento, a l’à cangiou unn-a zona primma segnâ da corsi d’ægua, creuze e piccin nuclei de case."
    },

    "Piazza Colombo": {
      it: "Piazza Colombo è una storica piazza di Genova situata nel quartiere di San Vincenzo, a pochi passi dalla centralissima Via XX Settembre. Realizzata nella seconda metà dell’Ottocento, è caratterizzata da ampi portici in stile neoclassico e dominata al centro dalla monumentale Fontana dei Cavallucci, originariamente situata presso il Ponte Reale, di fronte a Palazzo San Giorgio.",
      en: "Piazza Colombo is a historic square in Genoa’s San Vincenzo district, just a short walk from the central Via XX Settembre. Created in the second half of the 19th century, it is distinguished by broad Neoclassical arcades and by the monumental Fontana dei Cavallucci at its centre, originally located near Ponte Reale opposite Palazzo San Giorgio.",
      es: "Piazza Colombo es una histórica plaza de Génova situada en el barrio de San Vincenzo, a pocos pasos de la céntrica Via XX Settembre. Construida en la segunda mitad del siglo XIX, se caracteriza por sus amplios pórticos neoclásicos y por la monumental Fontana dei Cavallucci, situada en el centro y ubicada originalmente junto al Ponte Reale, frente al Palazzo San Giorgio.",
      fr: "La Piazza Colombo est une place historique de Gênes située dans le quartier de San Vincenzo, à quelques pas de la très centrale Via XX Settembre. Aménagée dans la seconde moitié du XIXe siècle, elle se distingue par ses vastes arcades néoclassiques et par la monumentale Fontana dei Cavallucci en son centre, autrefois située près du Ponte Reale, face au Palazzo San Giorgio.",
      ar: "ساحة كولومبو هي ساحة تاريخية في جنوة، تقع في حي سان فينتشنزو على مسافة قصيرة من شارع فيا XX سيتّيمبري المركزي. أُنشئت في النصف الثاني من القرن التاسع عشر، وتتميز بأروقتها الواسعة ذات الطراز الكلاسيكي الجديد وبنافورة الخيول الصغيرة الضخمة في وسطها، والتي كانت تقع أصلاً قرب بونتي رياله قبالة قصر سان جورجيو.",
      ru: "Пьяцца Коломбо — историческая площадь Генуи в районе Сан-Винченцо, в нескольких шагах от центральной Виа XX Сеттембре. Она была создана во второй половине XIX века и отличается просторными неоклассическими портиками. В центре находится монументальный фонтан Каваллуччи, первоначально стоявший у Понте-Реале напротив Палаццо Сан-Джорджо.",
      zh: "哥伦布广场是热那亚的一座历史广场，位于圣温琴佐区，距离市中心的九月二十日街仅几步之遥。广场建于19世纪下半叶，以宽阔的新古典主义拱廊为特色，中央矗立着宏伟的小马喷泉。这座喷泉最初位于圣乔治宫对面的皇家桥附近。",
      lij: "Ciassa Colombo a l’é ’na ciassa stöica de Zena, into quartê de San Vinçenso, a doî pasci da centralissima Via XX Settembre. Fæta inta seconda metæ de l’Ottoçento, a l’é caratterizzâ da grandi portici neoclassichi e, into mezo, da monumentale Fontann-a di Cavallucci, ch’a l’êa in origine apreuvo a-o Ponte Reale, davanti a-o Palaçio San Zòrzo."
    },

    "Ponte Monumentale": {
      it: "Il Ponte Monumentale è un’imponente struttura in marmo e pietra situata nel centro di Genova, che scavalca Via XX Settembre collegando le zone collinari di Carignano e dell’Acquasola. Costruito tra il 1893 e il 1895 al posto della storica Porta d’Arco, è alto 21 metri e presenta una grande arcata arricchita da colonne, nicchie e sculture neoclassiche.",
      en: "The Ponte Monumentale is an imposing marble and stone structure in central Genoa. It spans Via XX Settembre, connecting the elevated areas of Carignano and Acquasola. Built between 1893 and 1895 on the site of the historic Porta d’Arco, it stands 21 metres high and features a large arch decorated with columns, niches and Neoclassical sculptures.",
      es: "El Ponte Monumentale es una imponente estructura de mármol y piedra situada en el centro de Génova. Cruza por encima de Via XX Settembre y conecta las zonas elevadas de Carignano y Acquasola. Construido entre 1893 y 1895 en el lugar de la histórica Porta d’Arco, alcanza 21 metros de altura y presenta un gran arco decorado con columnas, hornacinas y esculturas neoclásicas.",
      fr: "Le Ponte Monumentale est une imposante structure de marbre et de pierre située dans le centre de Gênes. Il enjambe la Via XX Settembre et relie les secteurs élevés de Carignano et de l’Acquasola. Construit entre 1893 et 1895 à l’emplacement de l’ancienne Porta d’Arco, il mesure 21 mètres de haut et présente une grande arche ornée de colonnes, de niches et de sculptures néoclassiques.",
      ar: "بونتي مونومنتالي هو بناء ضخم من الرخام والحجر يقع في وسط جنوة، ويعبر فوق شارع فيا XX سيتّيمبري رابطاً منطقتي كارينيانو وأكواسولا المرتفعتين. شُيّد بين عامي 1893 و1895 في موقع بوابة بورتا داركو التاريخية، ويبلغ ارتفاعه 21 متراً، ويتميز بقوس كبير مزين بالأعمدة والكُوّات والمنحوتات الكلاسيكية الجديدة.",
      ru: "Монументальный мост — внушительное сооружение из мрамора и камня в центре Генуи. Он проходит над Виа XX Сеттембре, соединяя возвышенные районы Кариньяно и Аккуасола. Построенный в 1893–1895 годах на месте исторических ворот Порта-д’Арко, мост достигает 21 метра в высоту. Его большая арка украшена колоннами, нишами и неоклассическими скульптурами.",
      zh: "纪念桥是热那亚市中心一座宏伟的大理石和石砌建筑，横跨九月二十日街，连接卡里尼亚诺和阿夸索拉两处高地。它于1893年至1895年间在历史悠久的拱门旧址上建成，高21米，巨大的拱券饰有立柱、壁龛和新古典主义雕塑。",
      lij: "O Ponte Monumentale o l’é ’na grande struttura de marmo e pria into çentro de Zena. O passa in çimma a Via XX Settembre e o collega e zönn-e in äto de Caignan e de l’Acquasöa. Costruïo fra o 1893 e o 1895 a-o posto da stöica Pòrta d’Arco, o l’é erto 21 metri e o gh’à ’na grande arcâ con colonn-e, nicchie e sculture neoclassiche."
    },

    "Prima dei portici": {
      it: "Via Giulia era la principale strada seicentesca di Genova che, prima delle radicali trasformazioni urbanistiche di fine Ottocento, collegava l’antica Piazza San Domenico, l’odierna Piazza De Ferrari, con la Porta degli Archi. Il suo tracciato fu interamente demolito, livellato e allargato negli anni Novanta dell’Ottocento per fare spazio alla moderna Via XX Settembre.",
      en: "Via Giulia was Genoa’s main 17th-century street. Before the radical urban changes of the late 19th century, it connected the former Piazza San Domenico, now Piazza De Ferrari, with Porta degli Archi. Its route was completely demolished, levelled and widened during the 1890s to make way for the modern Via XX Settembre.",
      es: "Via Giulia era la principal calle genovesa del siglo XVII. Antes de las profundas transformaciones urbanísticas de finales del siglo XIX, conectaba la antigua Piazza San Domenico, actual Piazza De Ferrari, con la Porta degli Archi. Su trazado fue completamente demolido, nivelado y ensanchado durante la década de 1890 para dar paso a la moderna Via XX Settembre.",
      fr: "La Via Giulia était la principale rue génoise du XVIIe siècle. Avant les profondes transformations urbaines de la fin du XIXe siècle, elle reliait l’ancienne Piazza San Domenico, aujourd’hui Piazza De Ferrari, à la Porta degli Archi. Son tracé fut entièrement démoli, nivelé et élargi dans les années 1890 pour laisser place à la Via XX Settembre moderne.",
      ar: "كان شارع فيا جوليا الطريق الرئيسي في جنوة خلال القرن السابع عشر. وقبل التحولات العمرانية الجذرية في أواخر القرن التاسع عشر، كان يربط ساحة سان دومينيكو القديمة، وهي ساحة دي فيرّاري الحالية، ببوابة بورتا ديلي آركي. وقد هُدم مساره بالكامل وسُوّي ووُسّع خلال تسعينيات القرن التاسع عشر لإفساح المجال أمام شارع فيا XX سيتّيمبري الحديث.",
      ru: "Виа Джулия была главной улицей Генуи XVII века. До радикальных градостроительных преобразований конца XIX столетия она соединяла бывшую площадь Сан-Доменико, нынешнюю Пьяцца Де Феррари, с воротами Порта-дельи-Арки. В 1890-е годы улицу полностью снесли, выровняли и расширили, освободив место для современной Виа XX Сеттембре.",
      zh: "朱利亚街曾是17世纪热那亚最重要的街道。在19世纪末的大规模城市改造之前，它连接着旧圣多梅尼科广场，即今天的德·费拉里广场，以及拱门城门。19世纪90年代，原有道路被全部拆除、平整并拓宽，为现代九月二十日街让出空间。",
      lij: "Via Giulia a l’êa a prinçipâ stradda do Seiçento de Zena. Primma de grande trasformaçioin urbanistiche da fin de l’Ottoçento, a collegava l’antiga Ciassa San Domenico, l’attuâ Ciassa De Ferrari, co-a Pòrta di Archi. Into anni Novanta de l’Ottoçento, o seu tracciou o l’é stæto tutto demolîo, spianou e slargou pe fâ spaçio a-a moderna Via XX Settembre."
    },

    "Lavori alle linee del tram": {
      it: "I lavori per l’installazione delle prime linee del tram elettrico in Via XX Settembre si svolsero alla fine dell’Ottocento, parallelamente al completamento della via stessa e all’inaugurazione del Ponte Monumentale, avvenuta nel 1895.",
      en: "Work to install the first electric tram lines in Via XX Settembre took place in the late 19th century, alongside the completion of the street itself and the inauguration of the Ponte Monumentale in 1895.",
      es: "Las obras para instalar las primeras líneas de tranvía eléctrico en Via XX Settembre se llevaron a cabo a finales del siglo XIX, paralelamente a la finalización de la propia calle y a la inauguración del Ponte Monumentale en 1895.",
      fr: "Les travaux d’installation des premières lignes de tramway électrique sur la Via XX Settembre furent réalisés à la fin du XIXe siècle, parallèlement à l’achèvement de la rue et à l’inauguration du Ponte Monumentale en 1895.",
      ar: "نُفذت أعمال تركيب أولى خطوط الترام الكهربائي في شارع فيا XX سيتّيمبري في أواخر القرن التاسع عشر، بالتزامن مع استكمال الشارع نفسه وافتتاح بونتي مونومنتالي عام 1895.",
      ru: "Работы по прокладке первых линий электрического трамвая на Виа XX Сеттембре велись в конце XIX века, одновременно с завершением строительства самой улицы и открытием Монументального моста в 1895 году.",
      zh: "九月二十日街第一批有轨电车电气线路的铺设工程始于19世纪末，与街道本身的竣工以及1895年纪念桥的落成同期进行。",
      lij: "I travaggi pe mette e primme linn-e do tram elettrico in Via XX Settembre son stæti fæti a-a fin de l’Ottoçento, into mæximo periodo do completamento da stradda e de l’inauguraçion do Ponte Monumentale, into 1895."
    },

    "Incrocio Via Galata": {
      it: "Via Galata è una delle strade commerciali più animate del centro di Genova. Incrocia perpendicolarmente Via XX Settembre e si estende fino a Piazza Colombo, offrendo un percorso pedonale ricco di storiche focaccerie, caffè, botteghe artigiane e negozi di abbigliamento.",
      en: "Via Galata is one of the liveliest shopping streets in central Genoa. It crosses Via XX Settembre at right angles and extends as far as Piazza Colombo, offering a pedestrian route lined with historic focaccia bakeries, cafés, craft shops and clothing stores.",
      es: "Via Galata es una de las calles comerciales más animadas del centro de Génova. Cruza perpendicularmente Via XX Settembre y se extiende hasta Piazza Colombo, ofreciendo un recorrido peatonal lleno de históricas focaccerie, cafeterías, talleres artesanales y tiendas de ropa.",
      fr: "La Via Galata est l’une des rues commerçantes les plus animées du centre de Gênes. Elle croise perpendiculairement la Via XX Settembre et se prolonge jusqu’à la Piazza Colombo, offrant un parcours piéton bordé de focaccerie historiques, de cafés, de boutiques artisanales et de magasins de vêtements.",
      ar: "يُعد شارع غالاتا أحد أكثر شوارع التسوق حيوية في وسط جنوة. ويتقاطع عمودياً مع شارع فيا XX سيتّيمبري ويمتد حتى ساحة كولومبو، موفراً مساراً للمشاة تنتشر على جانبيه مخابز الفوكاتشا التاريخية والمقاهي والورش الحرفية ومتاجر الملابس.",
      ru: "Виа Галата — одна из самых оживлённых торговых улиц центра Генуи. Она пересекает Виа XX Сеттембре под прямым углом и продолжается до Пьяцца Коломбо. Вдоль пешеходного маршрута расположены исторические фокаччерии, кафе, ремесленные лавки и магазины одежды.",
      zh: "加拉塔街是热那亚市中心最热闹的商业街之一。它与九月二十日街垂直相交，一直延伸至哥伦布广场。沿步行路线分布着历史悠久的佛卡夏饼店、咖啡馆、手工作坊和服装店。",
      lij: "Via Galata a l’é unn-a de stradde comerciaæ ciù vive do çentro de Zena. A taggia Via XX Settembre a angolo drito e a va finn-a Ciassa Colombo, con un percorso pe-i pedoin pin de stöiche focaccerie, cafê, botteghe artigiann-e e negozzi de vestî."
    },

    "Presso Piccapietra": {
      it: "Nei primi anni del Novecento, l’ingresso a Piccapietra da Via XX Settembre rappresentava un punto di netto contrasto urbanistico. Mentre la nuova Via XX Settembre si presentava già come un monumentale e sfarzoso asse rettilineo, fiancheggiato da imponenti palazzi in stile liberty ed eclettico, l’accesso verso l’adiacente colle di Piccapietra introduceva a una realtà radicalmente diversa.",
      en: "In the early 20th century, the entrance to Piccapietra from Via XX Settembre marked a striking urban contrast. While the newly built Via XX Settembre already appeared as a grand and lavish straight avenue lined with imposing Art Nouveau and Eclectic buildings, the entrance towards the neighbouring Piccapietra hill led into a radically different setting.",
      es: "A principios del siglo XX, la entrada a Piccapietra desde Via XX Settembre representaba un marcado contraste urbanístico. Mientras la recién construida Via XX Settembre ya se presentaba como un monumental y suntuoso eje rectilíneo, flanqueado por imponentes edificios modernistas y eclécticos, el acceso hacia la cercana colina de Piccapietra introducía en una realidad radicalmente distinta.",
      fr: "Au début du XXe siècle, l’entrée de Piccapietra depuis la Via XX Settembre créait un contraste urbain saisissant. Alors que la nouvelle Via XX Settembre se présentait déjà comme une avenue rectiligne monumentale et somptueuse, bordée d’imposants immeubles Art nouveau et éclectiques, l’accès à la colline voisine de Piccapietra conduisait vers un environnement radicalement différent.",
      ar: "في أوائل القرن العشرين، كان مدخل بيكّابيترا من شارع فيا XX سيتّيمبري يمثل تبايناً عمرانياً واضحاً. فبينما كان الشارع الجديد يبدو محوراً مستقيماً فخماً وضخماً تصطف على جانبيه مبانٍ مهيبة بطرازي الآرت نوفو والانتقائية، كان الطريق المؤدي إلى تل بيكّابيترا المجاور ينفتح على بيئة مختلفة جذرياً.",
      ru: "В начале XX века вход в Пиккапьетра со стороны Виа XX Сеттембре создавал резкий градостроительный контраст. Новая Виа XX Сеттембре уже представляла собой монументальный и роскошный прямой проспект, окружённый внушительными зданиями в стилях модерн и эклектика, тогда как путь к соседнему холму Пиккапьетра вёл в совершенно иную городскую среду.",
      zh: "20世纪初，从九月二十日街进入皮卡彼得拉的入口呈现出鲜明的城市景观反差。新建的九月二十日街已经是一条宏伟华丽的笔直大道，两侧排列着气势恢宏的新艺术风格和折衷主义建筑；而通往附近皮卡彼得拉山丘的入口，则将人们带入截然不同的环境。",
      lij: "A-o prinçipio do Neuveçento, l’intrâ a Piccapria da Via XX Settembre o mostrava un contrasto urbanistico ben netto. A neuva Via XX Settembre a l’êa za un asse drito, monumentale e sfarzoso, con grandi palaçi in stile Liberty e eclettico; l’accesso verso l’ægua colinn-a de Piccapria o portava invece inte ’na realtæ completamente diversa."
    },

    "Via XX settembre alta": {
      it: "La parte alta di Via XX Settembre, compresa tra il Ponte Monumentale e Piazza De Ferrari, era il salotto liberty più sfarzoso di Genova. Questa sezione era caratterizzata da monumentali portici alti fino a quindici metri, pavimentati con raffinati mosaici in marmo e illuminati dai primi lampioni elettrici della città.",
      en: "The upper section of Via XX Settembre, between the Ponte Monumentale and Piazza De Ferrari, was Genoa’s most lavish Art Nouveau showcase. This stretch was distinguished by monumental arcades up to fifteen metres high, paved with refined marble mosaics and illuminated by some of the city’s first electric streetlights.",
      es: "La parte alta de Via XX Settembre, comprendida entre el Ponte Monumentale y Piazza De Ferrari, era el escaparate modernista más suntuoso de Génova. Este tramo se caracterizaba por sus monumentales pórticos de hasta quince metros de altura, pavimentados con refinados mosaicos de mármol e iluminados por algunas de las primeras farolas eléctricas de la ciudad.",
      fr: "La partie haute de la Via XX Settembre, entre le Ponte Monumentale et la Piazza De Ferrari, était la vitrine Art nouveau la plus somptueuse de Gênes. Ce tronçon se distinguait par des arcades monumentales pouvant atteindre quinze mètres de haut, pavées de délicates mosaïques de marbre et éclairées par certains des premiers réverbères électriques de la ville.",
      ar: "كان الجزء العلوي من شارع فيا XX سيتّيمبري، بين بونتي مونومنتالي وساحة دي فيرّاري، أفخم واجهة لطراز الآرت نوفو في جنوة. وتميز هذا الجزء بأروقة ضخمة يصل ارتفاعها إلى خمسة عشر متراً، مرصوفة بفسيفساء رخامية دقيقة ومضاءة ببعض أوائل مصابيح الشوارع الكهربائية في المدينة.",
      ru: "Верхняя часть Виа XX Сеттембре, между Монументальным мостом и Пьяцца Де Феррари, была самым роскошным образцом генуэзского модерна. Этот участок отличался монументальными портиками высотой до пятнадцати метров, полами с изысканной мраморной мозаикой и одними из первых электрических фонарей города.",
      zh: "九月二十日街上段位于纪念桥与德·费拉里广场之间，曾是热那亚最华丽的新艺术风格展示区。这一路段以高达15米的宏伟拱廊为特色，地面铺设精美的大理石马赛克，并由这座城市最早的一批电灯照明。",
      lij: "A parte erta de Via XX Settembre, fra o Ponte Monumentale e Ciassa De Ferrari, a l’êa o salotto Liberty ciù sfarzoso de Zena. Sto tratto o l’êa caratterizzou da portici monumentali, erti finn-a quinze metri, co-o sò pavimento de fin mosaichi de marmo e illuminæ da unn-i di primmi lampioin eletrichi da çittæ."
    },

    "Via XX settembre bassa": {
      it: "La parte bassa di Via XX Settembre si presenta come un ampio viale rettilineo, più aperto e luminoso rispetto alla parte alta. Fiancheggiata da imponenti palazzi eclettici e liberty, ospitava numerosi locali e caffè; qui si trova anche il grande Mercato Orientale, inaugurato nel 1899.",
      en: "The lower section of Via XX Settembre is a broad, straight avenue, more open and brighter than its upper section. Lined with imposing Eclectic and Art Nouveau buildings, it once accommodated numerous venues and cafés. It is also home to the large Mercato Orientale, opened in 1899.",
      es: "La parte baja de Via XX Settembre se presenta como una amplia avenida rectilínea, más abierta y luminosa que la parte alta. Flanqueada por imponentes edificios eclécticos y modernistas, albergaba numerosos locales y cafés. Aquí se encuentra también el gran Mercato Orientale, inaugurado en 1899.",
      fr: "La partie basse de la Via XX Settembre se présente comme une large avenue rectiligne, plus ouverte et lumineuse que sa partie haute. Bordée d’imposants immeubles éclectiques et Art nouveau, elle accueillait de nombreux établissements et cafés. On y trouve également le grand Mercato Orientale, inauguré en 1899.",
      ar: "يظهر الجزء السفلي من شارع فيا XX سيتّيمبري كجادة واسعة ومستقيمة، أكثر انفتاحاً وإشراقاً من الجزء العلوي. وتصطف على جانبيه مبانٍ مهيبة بالطرازين الانتقائي والآرت نوفو، وكان يضم العديد من المقاهي والمرافق. كما يوجد هنا سوق ميركاتو أورينتاله الكبير، الذي افتُتح عام 1899.",
      ru: "Нижняя часть Виа XX Сеттембре представляет собой широкий прямой проспект, более открытый и светлый, чем верхний участок. Вдоль него стоят внушительные здания в стилях эклектика и модерн; прежде здесь находилось множество заведений и кафе. Здесь же расположен большой Восточный рынок, открытый в 1899 году.",
      zh: "九月二十日街下段是一条宽阔笔直的大道，比上段更加开阔明亮。街道两侧排列着宏伟的折衷主义和新艺术风格建筑，过去曾有许多休闲场所和咖啡馆。1899年开业的大型东方市场也坐落于此。",
      lij: "A parte bassa de Via XX Settembre a l’é un grande viale drito, ciù averto e luminoso che a parte erta. Longo a stradda gh’é di imponenti palaçi eclettichi e Liberty; ’na votta ghe ëa tanti locali e cafê. Chi gh’é anche o grande Mercou Orientale, inaugurou into 1899."
    },

    "Via Aurelia": {
      it: "La Via Aurelia a Voltri costituisce la spina dorsale costiera del quartiere più occidentale di Genova. Nota localmente come Via Camozzini e Via Ventimiglia, attraversa l’antico borgo marinaro correndo parallela alla spiaggia e all’ampia passeggiata a mare.",
      en: "The Via Aurelia in Voltri forms the coastal backbone of Genoa’s westernmost district. Known locally as Via Camozzini and Via Ventimiglia, it crosses the old seaside village parallel to the beach and the broad seafront promenade.",
      es: "La Vía Aurelia en Voltri constituye el eje costero del barrio más occidental de Génova. Conocida localmente como Via Camozzini y Via Ventimiglia, atraviesa el antiguo pueblo marinero en paralelo a la playa y al amplio paseo marítimo.",
      fr: "La Via Aurelia à Voltri constitue l’axe côtier du quartier le plus occidental de Gênes. Connue localement sous les noms de Via Camozzini et Via Ventimiglia, elle traverse l’ancien village maritime parallèlement à la plage et à la vaste promenade du front de mer.",
      ar: "يشكل طريق أوريليا في فولتري المحور الساحلي للحي الواقع في أقصى غرب جنوة. ويُعرف محلياً باسم فيا كاموتسّيني وفيا فينتيميليا، ويعبر القرية البحرية القديمة موازياً للشاطئ وللممشى البحري الواسع.",
      ru: "Виа Аурелия в Вольтри образует главную прибрежную ось самого западного района Генуи. На местном уровне она известна как Виа Камоццини и Виа Вентимилья и пересекает старинный приморский посёлок параллельно пляжу и широкой набережной.",
      zh: "沃尔特里的奥雷利亚大道构成热那亚最西部街区的滨海主干道。它在当地被称为卡莫齐尼街和文蒂米利亚街，穿过古老的海滨村镇，与海滩和宽阔的滨海步道平行延伸。",
      lij: "A Via Aurelia a Votri a l’é a spinn-a dorsâ da costa do quartê ciù a ponente de Zena. Conosciûa localmente comme Via Camozzini e Via Ventimiglia, a passa pe l’antigo borgo mainâ, parallela a-a spiaggia e a-a grande passeggiâ a-o mâ."
    }
  });
})();
